var scwin = (typeof scwin === "undefined") ? {} : scwin;

// TODO: WebSquare submission을 구성한 뒤 이 호환 함수를 교체하세요.
scwin.xpTransaction = function() {
    console.warn("[마이그레이션 TODO] XPlatform transaction 호출을 WebSquare submission으로 변환해야 합니다.", arguments);
};


scwin.btnSearch_onclick = function(e)
{
    var obj = $p.getComponentById("btnSearch");
    console.log(obj.getID());
    scwin.fnSearch();
};

scwin.fnSearch = function()
{
    scwin.xpTransaction("search", "/sample/search.do", "dsSearch=dsSearch", "dsList=dsList", "", "fnCallback");
};

scwin.fnCallback = function(svcId, errCode, errMsg)
{
    scwin.fnSetResult();
};

scwin.fnSetResult = function()
{
    console.log("완료");
};

scwin.fnUnused = function()
{
    console.log("미사용");
};
